import { z } from 'zod';

// ============================================================
// 枚举定义
// ============================================================

/** 天气类型 */
const 天气Enum = z.enum(['晴', '阴', '雨', '雪', '雾', '风暴', '多云']);

/** 角色存活状态 */
const 存活状态Enum = z.enum(['存活', '感染', '丧尸', '死亡']);

/** 阵营归属 */
const 阵营Enum = z.enum(['盟友', '友善', '中立', '敌对']);

/** 据点安全等级 */
const 安全等级Enum = z.enum(['安全', '警戒', '危险']);

// ============================================================
// 子结构定义
// ============================================================

/** 角色之间的关系 */
const 关系Schema = z.record(z.string(), z.object({
  /** 关系值 -100=死敌 0=中立 100=挚友/恋人 */
  关系值: z.number().min(-100).max(100),
  /** 对该角色的主观看法 */
  看法: z.string(),
}));

/** 单个角色的完整信息 */
const 角色信息Schema = z.object({
  存活状态: 存活状态Enum,
  /** 体能状况 0~100 */
  体能: z.number().min(0).max(100),
  /** 精神状态 0~100 */
  精神: z.number().min(0).max(100),
  /** 身体具体状况描述 */
  身体状况: z.string(),
  /** 精神具体状况描述 */
  精神状况: z.string(),
  /** 当前装备的武器 */
  武器: z.string(),
  /** 当前穿着的服装 */
  服装: z.string(),
  /** 移动方式（步行/驾车/骑行等） */
  移动方式: z.string(),
  /** 当前所在位置 */
  当前位置: z.string(),
  /** 对主角的阵营归属 */
  阵营: 阵营Enum,
  /** 与其他角色的关系（key=角色姓名） */
  关系: 关系Schema,
});

/** 载具信息（key=载具名称） */
const 载具信息Schema = z.record(z.string(), z.object({
  /** 载具当前状态描述 */
  状态详情: z.string(),
  /** 剩余能量（油量/电量等） */
  剩余能量: z.number(),
}));

/** 物品信息（key=物品名称） */
const 物品信息Schema = z.record(z.string(), z.object({
  /** 持有数量 */
  数量: z.number(),
  /** 物品描述 */
  描述: z.string(),
}));

/** 事件信息（key=事件名称） */
const 事件信息Schema = z.record(z.string(), z.object({
  /** 事件描述 */
  描述: z.string(),
  /** 事件强度等级 */
  强度: z.number(),
  /** 事件触发时间 */
  触发时间: z.string(),
}));

// ============================================================
// 根 Schema
// ============================================================

export const Schema = z.object({
  /** 时空相关的环境信息 */
  时空信息: z.object({
    /** 当前日期，格式 YYYY-MM-DD */
    日期: z.string(),
    /** 当前时间，格式 HH:MM */
    时间: z.string(),
    /** 当前所在地点 */
    地点: z.string(),
    /** 当前天气 */
    天气: 天气Enum,
  }),

  /** 世界宏观状态 */
  世界信息: z.object({
    /** 幸存人口比例 0~100 */
    人口: z.number().min(0).max(100),
    /** 社会秩序程度 0~100 */
    秩序: z.number().min(0).max(100),
    /** 基础设施完整度 0~100 */
    基建: z.number().min(0).max(100),
    /** 物资充裕度 0~100 */
    资源: z.number().min(0).max(100),
    /** 社会伦理维持度 0~100 */
    伦理: z.number().min(0).max(100),
  }),

  /** 主角（玩家角色）的个人状态 */
  主角信息: z.object({
    /** 姓名 */
    姓名: z.string(),
    /** 存活状态 */
    存活状态: 存活状态Enum,
    /** 体能状况 0~100 */
    体能: z.number().min(0).max(100),
    /** 精神状态 0~100 */
    精神: z.number().min(0).max(100),
    /** 身体具体状况描述 */
    身体状况: z.string(),
    /** 精神具体状况描述 */
    精神状况: z.string(),
    /** 当前装备的武器 */
    武器: z.string(),
    /** 当前穿着的服装 */
    服装: z.string(),
    /** 移动方式 */
    移动方式: z.string(),
    /** 当前所在位置 */
    当前位置: z.string(),
  }),

  /** NPC 角色信息（key=角色姓名） */
  角色信息: z.record(z.string(), 角色信息Schema),

  /** 团队资源与设施 */
  团队信息: z.object({
    /** 据点/基地信息 */
    据点信息: z.object({
      /** 据点位置 */
      位置: z.string(),
      /** 据点安全等级 */
      安全等级: 安全等级Enum,
    }),
    /** 载具信息（key=载具名称） */
    载具信息: 载具信息Schema,
    /** 物品清单（key=物品名称） */
    物品信息: 物品信息Schema,
  }),

  /** 剧情事件记录（key=事件名称） */
  事件信息: 事件信息Schema,
});

export type Schema = z.output<typeof Schema>;
